mapper.insert:
INSERT INTO xxl_ai_session (
	agent_uuid, visitor_id, title, add_time, update_time
) VALUES (
	 #{agentUuid}, #{visitorId}, #{title}, NOW(), NOW()
 );

mapper.update:
UPDATE xxl_ai_session
SET update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT 
FROM xxl_ai_session AS t
WHERE t.id = #{id}

SELECT t.id, t.agent_uuid, a.name AS agent_name, t.visitor_id, t.title, t.add_time, t.update_time FROM xxl_ai_session AS t JOIN xxl_ai_agent AS a ON a.uuid = t.agent_uuid WHERE a.space_id = #{spaceId}
AND a.id = #{agentId}
AND t.title like CONCAT(CONCAT('%', #{title}), '%')
AND t.visitor_id like CONCAT(CONCAT('%', #{visitorId}), '%')
ORDER BY t.id DESC LIMIT #{offset}, #{pagesize}

SELECT count(1) FROM xxl_ai_session AS t JOIN xxl_ai_agent AS a ON a.uuid = t.agent_uuid WHERE a.space_id = #{spaceId}
AND a.id = #{agentId}
AND t.title like CONCAT(CONCAT('%', #{title}), '%')
AND t.visitor_id like CONCAT(CONCAT('%', #{visitorId}), '%')
